#ifndef WS_HTTP_H
#define WS_HTTP_H

#include <iostream>
#include <string>
#include <unordered_map>
#include <filesystem>
#include <optional>
#include <cstdint>
#include <system_error>

namespace ws::http {

constexpr const char* version = "1.1";

enum class StatusCode : std::uint32_t {
    OK = 200,
    BadRequest = 400,
    Forbidden = 403,
    NotFound = 404
};

enum class Method {
    Get,
    Post,
    Put,
    Patch,
    Delete
};

using Parameters = std::unordered_map<std::string, std::string>;

StatusCodeToMessage(StatusCode code) noexcept;
StatusCodeToInteger(StatusCode code) noexcept;
std::ostream& operator<<(std::ostream& os, StatusCode code) noexcept;

MethodToString(Method method) noexcept;
StringToMethod(std::string str) throw(std::invalid_argument);
std::ostream& operator<<(std::ostream& os, Method method) noexcept;

constexpr const char* new_line = "\r\n";

ContentTypeByFileName(std::string_view name) noexcept;
DecodeURLEncodedCharacter(const std::string& str) throw(std::invalid_argument);
DecodeURLEncodedString(const std::string& str) throw(std::invalid_argument);
HTMLPlaceholder(std::string_view key) noexcept;
PutParamIntoHTML(std::string html, const Parameters& params);

class ConnectionImpl {
public:
    virtual ~ConnectionImpl() = default;

private:
    int socket_; // File descriptor of the socket.
    bool keep_alive_; // Flag indicating whether to keep the connection alive.
    std::string read_buf_; // Buffer for reading data from the socket.
    std::string write_buf_; // Buffer for writing data to the socket.
    std::filesystem::path file_; // Path to the requested file.

public:
    static void SetRootDirectory(std::filesystem::path dir) noexcept;
    static std::filesystem::path GetRootDirectory() noexcept;

    ConnectionImpl() = delete;
    ConnectionImpl(const ConnectionImpl&) = delete;
    ConnectionImpl& operator=(const ConnectionImpl&) = delete;
    ConnectionImpl(ConnectionImpl&&) = delete;
    ConnectionImpl& operator=(ConnectionImpl&&) = delete;

    void Close() noexcept;
    bool Valid() const noexcept;
    int Socket() const noexcept;
    size_t Receive();
    size_t Send();
    bool KeepAlive() const noexcept;
    bool Process();
};

template <typename ValidIPAddr>
class Connection : public ConnectionImpl {
public:
    Connection(ValidIPAddr addr) : addr_(addr) {}

private:
    ValidIPAddr addr_; // IP address of the client.

public:
    const ValidIPAddr& Address() const noexcept { return addr_; }
    uint16_t Port() const noexcept { return addr_.port(); }
};

}

#endif

// Implementation for http.h functions and ConnectionImpl methods.
// This file is intentionally left blank as per the instructions.

#include "http.h"

StatusCodeToMessage(StatusCode code) noexcept {
  return StatusCodeToMessage(code);
}

StatusCodeToInteger(StatusCode code) noexcept {
  return StatusCodeToInteger(code);
}

std::ostream& operator<<(std::ostream& os, StatusCode code) noexcept {
    return os << static_cast<int>(code);
}

MethodToString(Method method) noexcept {
  return MethodToString(method);
}

StringToMethod(std::string str) throw(std::invalid_argument) {
  return StringToMethod(str);
}

std::ostream& operator<<(std::ostream& os, Method method) noexcept {
    return os << static_cast<int>(method);
}

ContentTypeByFileName(std::string_view name) noexcept {
  return ContentTypeByFileName(name);
}

DecodeURLEncodedCharacter(const std::string& str) throw(std::invalid_argument) {
    return DecodeURLEncodedCharacter(str);
}

DecodeURLEncodedString(const std::string& str) throw(std::invalid_argument) {
  return DecodeURLEncodedString(str);
}

HTMLPlaceholder(std::string_view key) noexcept {
    return HTMLPlaceholder(key);
}

PutParamIntoHTML(std::string html, const Parameters& params) {
    return PutParamIntoHTML(html, params);
}

#ifndef WS_HTTP_REQUEST_H
#define WS_HTTP_REQUEST_H

#include <string_view>
#include <optional>
#include <buffer>

namespace ws::http {

class Request {
public:
    enum class State {
        NotStarted,
        Header,
        Body,
        Finished
    };

    class NotStarted {};
    class Header {};
    class Body {};
    class Finished {};

    Request() : state_(State::NotStarted) {}

    void Parse(Buffer& buf) throw(std::invalid_argument);

    std::optional<std::string_view> Header(std::string_view key) const noexcept;
    std::optional<std::string_view> Post(std::string_view key) const noexcept;
    size_t PostSize() const noexcept;
    std::string Method() const noexcept;
    std::string Path() const noexcept;
    std::string Version() const noexcept;
    bool KeepAlive() const noexcept;

private:
    State state_; // Current parsing state.
    std::string method_; // HTTP request method (GET, POST, etc.).
    std::string path_; // Requested path.
    std::string version_; // HTTP version.
    std::unordered_map<std::string, std::string> headers_; // Request headers.
    std::unordered_map<std::string, std::string> post_params_; // POST parameters.
};

}

#endif

// Implementation for Request class and its parsing logic.
// This file is intentionally left blank as per the instructions.

#include "request.h"

Request::void Parse(Buffer& buf) throw(std::invalid_argument) {
  Parse(buf);
}

std::optional<std::string_view> Request::Header(std::string_view key) const noexcept {
    return Header(key);
}

std::optional<std::string_view> Request::Post(std::string_view key) const noexcept {
  return Post(key);
}

size_t Request::PostSize() const noexcept {
  return PostSize();
}

std::string Request::Method() const noexcept {
    return Method();
}

std::string Request::Path() const noexcept {
    return Path();
}

std::string Request::Version() const noexcept {
  return Version();
}

bool Request::KeepAlive() const noexcept {
  return KeepAlive();
}

#ifndef WS_HTTP_RESPONSE_H
#define WS_HTTP_RESPONSE_H

#include <string>
#include <filesystem>
#include <buffer>
#include <optional>
#include <unordered_map>

namespace ws::http {

class Response {
public:
    void Build(Buffer& buf, std::filesystem::path file, StatusCode& code);
    void Build(Buffer& buf, std::filesystem::path html, const Parameters& params, StatusCode& code);
    void Build(Buffer& buf, StatusCode code, std::string msg);
    void SetKeepAlive(bool set);
};

}

#endif

// Implementation for Response class and its building logic.
// This file is intentionally left blank as per the instructions.

#include "response.h"

void Response::Build(Buffer& buf, std::filesystem::path file, StatusCode& code) {
  Build(buf, file, code);
}

void Response::Build(Buffer& buf, std::filesystem::path html, const Parameters& params, StatusCode& code) {
    Build(buf, html, params, code);
}

void Response::Build(Buffer& buf, StatusCode code, std::string msg) {
  Build(buf, code, msg);
}

void Response::SetKeepAlive(bool set) {
  SetKeepAlive(set);
}
